def is_interleave(s1, s2, s3):
    def helper(i, j):
        if i == len(s1) and j == len(s2):
            return i + j == len(s3)
        k = i + j
        if k >= len(s3):
            return False
        take_s1 = i < len(s1) and s1[i] == s3[k] and helper(i + 1, j)
        take_s2 = j < len(s2) and s2[j] == s3[k] and helper(i, j + 1)
        return take_s1 or take_s2                                 # either path succeeding is enough

    if len(s1) + len(s2) != len(s3):
        return False
    return helper(0, 0)


if __name__ == "__main__":
    s1 = "ab"
    s2 = "cd"
    s3 = "acbd"
    print(is_interleave(s1, s2, s3))

