def is_interleave(s1, s2, s3):
    n, m = len(s1), len(s2)
    if n + m != len(s3):
        return False
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True
    for i in range(1, n + 1):
        dp[i][0] = dp[i - 1][0] and s1[i - 1] == s3[i - 1]
    for j in range(1, m + 1):
        dp[0][j] = dp[0][j - 1] and s2[j - 1] == s3[j - 1]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            k = i + j - 1
            from_s1 = dp[i - 1][j] and s1[i - 1] == s3[k]              # the next character came from s1
            from_s2 = dp[i][j - 1] and s2[j - 1] == s3[k]                # the next character came from s2
            dp[i][j] = from_s1 or from_s2
    return dp[n][m]


